shape=[(0,1),(1,1),(2,0),(2,1),(3,1)]
H,W=21,21
matches=[]
for r in range(H-3):
 for c in range(W-1):
  coords=[(r+dr,c+dc) for dr,dc in shape]
  if all(grid[rr][cc]==0 for rr,cc in coords): matches.append((r,c,coords))
len(matches), [(r,c) for r,c,_ in matches]

def norm(points):
    mr=min(r for r,c in points); mc=min(c for r,c in points)
    return tuple(sorted((r-mr,c-mc) for r,c in points))
def variants(points):
    out=set()
    for refl in [False,True]:
      for k in range(4):
        ps=[]
        for r,c in points:
          if refl: c=-c
          for _ in range(k): r,c=c,-r
          ps.append((r,c))
        out.add(norm(ps))
    return sorted(out)
shape=norm([(0,1),(1,1),(2,0),(2,1),(3,1)])
vs=variants(shape)
len(vs),vs

matches2=[]
for sh in vs:
 h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
 for r in range(H-h+1):
