   coords=[(r+dr,c+dc) for dr,dc in sh]
   if all(grid[rr][cc]==0 for rr,cc in coords): matches2.append((sh,r,c,coords))
len(matches2), {tuple(sh) for sh,_,_,_ in matches2}

